/* Copyright © 2026 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ */package cn.zhuatech.airedteam.controller;import cn.zhuatech.airedteam.common.ApiResponse;import cn.zhuatech.airedteam.model.CampaignAudit;import cn.zhuatech.airedteam.service.RedTeamService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/ai-redteam")public class RedTeamController{private final RedTeamService service;public RedTeamController(RedTeamService s){service=s;}@PostMapping("/campaigns/run")@PreAuthorize("hasAnyRole('ADMIN','REDTEAM')")public ApiResponse<RedTeamService.CampaignResult>run(@Valid@RequestBody RedTeamService.CampaignRequest r,Authentication a){return ApiResponse.ok("红队活动运行完成",service.run(r,a.getName()));}@GetMapping("/audits")@PreAuthorize("hasAnyRole('ADMIN','AUDITOR')")public ApiResponse<List<CampaignAudit>>audits(){return ApiResponse.ok("审计查询成功",service.audits());}}
